CREATE OR REPLACE FUNCTION public.notify_device_config_updated()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
        BEGIN
            PERFORM pg_notify('device_config_updated', NEW.id::text);
            RETURN NEW;
        END;
        $function$

CREATE OR REPLACE FUNCTION public.notify_device_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM pg_notify('device_config_updated', NEW.id::TEXT);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$function$
